package io.github.artemkavg.spotube_plugin_soundcloud.core

private val PLACEHOLDERS = listOf(
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
)

fun placeholderArtwork(seed: String?): String {
    val hash = seed.orEmpty().fold(0) { acc, c -> (acc * 31 + c.code) and 0x7FFFFFFF }
    return PLACEHOLDERS[hash % PLACEHOLDERS.size]
}
